using System.Text;

namespace Invoicing;

/// <summary>Renders an invoice to a plain-text document.</summary>
public sealed class InvoiceRenderer
{
    public string Render(Invoice invoice, Account account)
    {
        var sb = new StringBuilder();

        AppendHeader(sb, invoice, account);
        var (net, vat) = AppendLines(sb, invoice);
        AppendTotals(sb, net, vat, account);
        AppendPaymentTerms(sb, account);

        return sb.ToString();
    }

    private static void AppendHeader(StringBuilder sb, Invoice invoice, Account account)
    {
        sb.AppendLine($"INVOICE {invoice.Number}");
        if (account.Name.Length > 0)
            sb.AppendLine(account.Name);

        switch (account.Kind)
        {
            case AccountKind.Business:
                sb.AppendLine("VAT registered");
                break;
            case AccountKind.Government:
                sb.AppendLine("Government purchase order");
                break;
            case AccountKind.Consumer:
                sb.AppendLine("Consumer");
                break;
        }
    }

    private static (decimal Net, decimal Vat) AppendLines(StringBuilder sb, Invoice invoice)
    {
        decimal net = 0m;
        decimal vat = 0m;

        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount < 0m)
                continue;

            decimal lineVat = line.NetAmount * line.VatRate;
            AppendLine(sb, line.Description, line.NetAmount, line.VatRate, lineVat);
            net += line.NetAmount;
            vat += lineVat;
        }

        return (net, vat);
    }

    private static void AppendLine(
        StringBuilder sb,
        string description,
        decimal netAmount,
        decimal vatRate,
        decimal lineVat)
    {
        if (vatRate == 0m)
            sb.AppendLine($"{description} {netAmount} (zero-rated)");
        else if (vatRate >= 0.2m)
            sb.AppendLine($"{description} {netAmount} (std {lineVat})");
        else
            sb.AppendLine($"{description} {netAmount} (reduced {lineVat})");

        if (description.Length > 40)
            sb.AppendLine("  (description truncated)");
    }

    private static void AppendTotals(
        StringBuilder sb,
        decimal net,
        decimal vat,
        Account account)
    {
        decimal discount = CalculateDiscount(net, account.Kind);
        decimal gross = net + vat - discount;
        if (gross < 0m)
            gross = 0m;

        sb.AppendLine($"NET {net} VAT {vat} DISC {discount} TOTAL {gross}");
    }

    private static decimal CalculateDiscount(decimal net, AccountKind accountKind)
    {
        if (net > 1000m && accountKind == AccountKind.Business)
            return net * 0.05m;
        if (net > 5000m)
            return net * 0.10m;
        return 0m;
    }

    private static void AppendPaymentTerms(StringBuilder sb, Account account)
    {
        if (account.Kind == AccountKind.Government)
            sb.AppendLine("Remit within 30 days");
        else
            sb.AppendLine("Remit within 14 days");
    }
}
